create table admins(id bigint unsigned auto_increment primary key,email varchar(254) not null unique,password_hash varchar(255) not null,session_token char(64),expires_at datetime,created_at timestamp default current_timestamp) charset=utf8mb4;create table gallery_items(id bigint unsigned auto_increment primary key,title varchar(160) not null,description text,image_path varchar(255) not null,event_date date,display_order int not null default 0,active boolean not null default true,created_at timestamp default current_timestamp,updated_at timestamp default current_timestamp on update current_timestamp) charset=utf8mb4;create table members(id bigint unsigned auto_increment primary key,name varchar(120) not null,designation varchar(80) not null,bio text,photo_path varchar(255),display_order int not null default 0,active boolean not null default true,created_at timestamp default current_timestamp,updated_at timestamp default current_timestamp on update current_timestamp) charset=utf8mb4;create table contact_messages(id bigint unsigned auto_increment primary key,name varchar(120) not null,email varchar(254) not null,mobile varchar(30),subject varchar(160) not null,message text not null,created_at timestamp default current_timestamp) charset=utf8mb4;create table donations(id bigint unsigned auto_increment primary key,donor_name varchar(120) not null,donor_email varchar(254) not null,donor_mobile varchar(30),amount int not null,currency char(3) not null default 'INR',razorpay_order_id varchar(80) unique,razorpay_payment_id varchar(80) unique,status enum('created','failed','paid') not null default 'created',created_at timestamp default current_timestamp,updated_at timestamp default current_timestamp on update current_timestamp) charset=utf8mb4;create table webhook_events(id bigint unsigned auto_increment primary key,provider varchar(32) not null,event_id varchar(160) not null,event_type varchar(80) not null,payload_hash char(64) not null,processed_at datetime,created_at timestamp default current_timestamp,unique key webhook_identity(provider,event_id)) charset=utf8mb4;
